<?php $csrf_token = (string) ($csrf_token ?? ''); $teachers = $teachers ?? []; $classes = $classes ?? []; $subjects = $subjects ?? []; $years = $years ?? []; $assignments = $assignments ?? []; ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="fw-bold text-primary mb-1">Affectations enseignants</h4><div class="text-muted">Enseignant → classe → matière → année scolaire</div></div></div>
<div class="card mb-4"><div class="card-header">Nouvelle affectation</div><div class="card-body"><form method="POST" action="<?= Router::url('affectations/save') ?>" class="row g-2 align-items-end"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf_token) ?>"><div class="col-md-3"><label class="form-label">Enseignant</label><select name="teacher_id" class="form-select" required><option value="">Choisir</option><?php foreach($teachers as $t): ?><option value="<?= (int)$t['id'] ?>"><?= htmlspecialchars($t['prenom'].' '.$t['nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Classe</label><select name="class_id" class="form-select" required><option value="">Choisir</option><?php foreach($classes as $c): ?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['libelle_complete'] ?? $c['nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Matière</label><select name="subject_id" class="form-select" required><option value="">Choisir</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>"><?= htmlspecialchars($s['nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Année</label><select name="school_year_id" class="form-select" required><?php foreach($years as $y): ?><option value="<?= (int)$y['id'] ?>" <?= $y['active'] ? 'selected' : '' ?>><?= htmlspecialchars($y['libelle']) ?></option><?php endforeach; ?></select></div><div class="col-md-1"><button class="btn btn-primary w-100" title="Ajouter"><i class="bi bi-plus-lg"></i></button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Enseignant</th><th>Classe</th><th>Matière</th><th>Année</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($assignments as $a): ?><tr><td><?= htmlspecialchars($a['enseignant_prenom'].' '.$a['enseignant_nom']) ?></td><td><?= htmlspecialchars($a['niveau_nom'].' '.$a['classe_nom']) ?></td><td><?= htmlspecialchars($a['matiere_nom']) ?></td><td><?= htmlspecialchars($a['annee']) ?></td><td><?= $a['status'] ? '<span class="badge bg-success">Actif</span>' : '<span class="badge bg-secondary">Inactif</span>' ?></td><td><form method="POST" action="<?= Router::url('affectations/toggle/'.$a['id']) ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf_token) ?>"><button class="btn btn-sm btn-outline-secondary">Activer/Désactiver</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
